from fractions import Fraction
from collections import deque


def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    jm = {a: b for a, b in jumps}

    def land(c: int) -> int:
        # Follow chained jumps until a cell with no jump is reached.
        while c in jm:
            c = jm[c]
        return c

    # Transitions from each non-final cell over all rolls.
    trans = {}
    for p in range(n):
        dests = []
        for r in range(1, m + 1):
            q = p + r
            if q > n:
                q = 2 * n - p - r
            dests.append(land(q))
        trans[p] = dests

    # Cells reachable from the start (cell n is absorbing and not expanded).
    reach = {0}
    dq = deque([0])
    while dq:
        p = dq.popleft()
        for q in trans[p]:
            if q != n and q not in reach:
                reach.add(q)
                dq.append(q)

    # Cells that can reach n, via the reversed graph.
    rev = {i: [] for i in range(n + 1)}
    for p in range(n):
        for q in trans[p]:
            rev[q].append(p)
    can = {n}
    dq = deque([n])
    while dq:
        q = dq.popleft()
        for p in rev[q]:
            if p not in can:
                can.add(p)
                dq.append(p)

    # A reachable cell that cannot reach n gives positive probability of never ending.
    if any(p not in can for p in reach):
        return None

    # Solve E[p] = 1 + (1/m) * sum E[q] over the closed reachable set, with E[n] = 0.
    S = sorted(reach)
    idx = {p: i for i, p in enumerate(S)}
    k = len(S)
    A = [[Fraction(0)] * (k + 1) for _ in range(k)]
    for p in S:
        i = idx[p]
        A[i][i] += 1
        A[i][k] = Fraction(1)
        for q in trans[p]:
            if q != n:
                A[i][idx[q]] -= Fraction(1, m)

    # Gauss-Jordan elimination with exact fractions.
    for col in range(k):
        piv = next(r for r in range(col, k) if A[r][col] != 0)
        A[col], A[piv] = A[piv], A[col]
        pv = A[col][col]
        A[col] = [x / pv for x in A[col]]
        for r in range(k):
            if r != col and A[r][col] != 0:
                f = A[r][col]
                A[r] = [a - f * b for a, b in zip(A[r], A[col])]

    ans = A[idx[0]][k]
    return [ans.numerator, ans.denominator]
